pub fn phase_at_epoch(&self, epoch: Epoch) -> Phase {
    self.fork_epochs()
        .take_while(|(_, fork_epoch)| *fork_epoch <= epoch)
        .map(|(phase, _)| phase)
        .last()
        .unwrap_or(Phase::Phase0)
}

